const express = require('express');
const router = express.Router();
const pool = require('../db');
const {query, getLastId} = require("../models/models")

// POST /api/enrollments  (faz inscrição e gera parcelas na tabela payments)
router.post('/add', async (req, res) => {
  try {
    const { student_id, class_id, enrollment_date, selected_parcela, parcelas_total } = req.body;

    
    // pegar course_id da turma
    const clsResult = await query('SELECT course_id FROM classes WHERE id = ?', [class_id]);
    const clsRows = clsResult[0]; // mysql2 retorna [rows, fields]
    if (!clsRows || clsRows.length === 0) {
      return res.status(400).json({ error: 'invalid_class' });
    }
    
    const courseId = clsRows?.course_id;
    
    // pegar preço do curso
    const courseResult = await query('SELECT price, payment_parcelas FROM courses WHERE id = ?', [courseId]);
    const courseRows = courseResult[0];
    if (!courseRows || courseRows.length === 0) {
      return res.status(400).json({ error: 'course_not_found' });
    }

    const price = parseFloat(courseRows?.price || 0);
    const parcelas = parseInt(courseRows?.payment_parcelas) || 1;
    const valor_por_parcela = +(price / parcelas).toFixed(2);

    // inserir enrollment
    const dateStr = enrollment_date
    ? new Date(enrollment_date).toISOString().split('T')[0]
    : new Date().toISOString().split('T')[0];
    
    const enrResult = await query(
      'INSERT INTO enrollments (student_id,class_id,enrollment_date,parcelas_total,parcelas_pagas,valor_por_parcela) VALUES (?,?,?,?,?,?)',
      [student_id, class_id, dateStr, parcelas, selected_parcela, valor_por_parcela]
    );
    
    
    const enrollmentId = enrResult?.insertId;

    // criar payments
    const payments = [];
    const today = new Date();
    for (let i = 1; i <= parcelas; i++) {
      const due = new Date(today.getFullYear(), today.getMonth() + i, today.getDate());
      const dueDateStr = due.toISOString().split('T')[0];
      payments.push([
        enrollmentId,
        student_id,
        i,
        valor_por_parcela,
        'AOA',
        'offline',
        'pending',
        null,
        dueDateStr,
      ]);
    }

    if (payments.length > 0) {
      await query(
        'INSERT INTO payments (enrollment_id,student_id,parcela_numero,amount,currency,method,status,transaction_reference,due_date) VALUES ?',
        [payments]
      );
    }

    const rows = await query('SELECT * FROM enrollments WHERE id = ?', [enrollmentId]);
    res.json(rows[0]);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'internal_error' });
  }
});


router.post('/addTeacher', async (req, res) => {
  try {

    const {name, email, contact} = req.body;

    const existing =  await query("SELECT * FROM instructors WHERE email = ? ", [email]);

    if(existing.length > 0){
      res.status(401).json({message: "Já existe um instrutor cadastrado com este email!"})
    }else{

      
      const result = await query("INSERT INTO instructors(name, email, contact) VALUES(?, ?, ?)", [
        name, email, contact
      ])
      
      const insertId = result?.insertId;
      
    if(insertId){
      res.status(200).json({message: "Instrutor adicionado!"})
    }else{
      res.status(501).json({message: "Erro ao adicionar instrutor"});
    }
  }
    
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'internal_error' });
  }
})

router.post("/teachers", async (req, res) => {
  try {
    const { 
      minId, 
      limit = 20, 
      offset = 0, 
      name, 
      email 
    } = req.body;

    const filters = [];
    const params = [];

    if (minId) {
      filters.push("i.id >= ?");
      params.push(Number(minId));
    }

    if (name) {
      filters.push("LOWER(i.name) LIKE ?");
      params.push(`%${name.toLowerCase()}%`);
    }

    if (email) {
      filters.push("LOWER(i.email) LIKE ?");
      params.push(`%${email.toLowerCase()}%`);
    }

    const whereClause = filters.length ? `WHERE ${filters.join(" AND ")}` : "";

    // QUERY segura para MariaDB
    const sql = `
      SELECT 
        i.id,
        i.name,
        i.email,
        i.contact,
        COUNT(DISTINCT cl.id) AS total_classes,
        CONCAT('[', GROUP_CONCAT(DISTINCT JSON_OBJECT('name', c.title)), ']') AS courses
      FROM instructors i
      LEFT JOIN classes cl ON cl.instructor_id = i.id
      LEFT JOIN courses c ON c.id = cl.course_id
      ${whereClause}
      GROUP BY i.id, i.name, i.email, i.contact
      ORDER BY i.id ASC
      LIMIT ?
      OFFSET ?
    `;

    params.push(Number(limit));
    params.push(Number(offset));

    const result = await query(sql, params);

    // parse seguro do JSON retornado pelo MariaDB
    const data = result.map(row => {
      let courses = [];
      try {
        courses = row.courses ? JSON.parse(row.courses) : [];
      } catch (err) {
        courses = [];
      }

      return {
        id: row.id,
        name: row.name,
        email: row.email,
        contact: row.contact,
        total_classes: row.total_classes,
        status: row.total_classes > 0 ? "active" : "inactive",
        courses: courses.map(c => c.name).join(", "),
      };
    });

    return res.status(200).json({
      data,
      pagination: {
        limit: Number(limit),
        offset: Number(offset),
        returned: data.length,
      },
    });
  } catch (error) {
    console.error("GET /teachers error:", error);
    return res.status(500).json({ error: "internal_error" });
  }
});

router.get("/classes", async(req, res) => {
  try {

    const sql = `
      SELECT 
        cl.id,
        cl.name as code,
        c.title AS course,
        i.name AS instructor,
        cl.schedule,
        cl.start_date,
        cl.end_date,
        IFNULL(e.enrolled, 0) AS enrolled,
        cl.capacity,
        c.price,
        c.payment_parcelas,
        cl.status
      FROM classes cl
      LEFT JOIN courses c ON c.id = cl.course_id
      LEFT JOIN instructors i ON i.id = cl.instructor_id
      LEFT JOIN (
        SELECT class_id, COUNT(*) AS enrolled
        FROM enrollments
        GROUP BY class_id
      ) e ON e.class_id = cl.id
      LIMIT 100;
    `;
    
    const result = await query(sql, []);

    if(result.length > 0){
      const data = []
      result.map(r => {
        data.push({
          ...r,
          status: r?.status ? r.status : "upcoming"
        })
      })
      res.status(200).json(data)
    }else{
      res.status(404).json([])
    }

  } catch (error) {
    console.error("GET /teachers error:", error);
    return res.status(500).json({ error: "internal_error" });
  }
});

router.post("/addClass", async(req, res) => {
  try{

    const {
    course_id,
    instructor_id,
    capacity,
    start_date,
    end_date,
    name,
    schedule
} = req.body;

  if(!course_id && !instructor_id && !capacity && !start_date && !end_date && !name, !schedule){
    res.status(401).json({message: "Preencha todos os campos!"})
  }else{

    const lastId = await getLastId("classes", "id");

    const existis = await query("SELECT * FROM classes WHERE course_id = ?", [name]);
    let code = "";
    
    if(existis){
      code = name+"-"+Number(lastId + 1);
    }else{
      code = name+"-"+ 1;
    }
    
    const result = await pool.query("INSERT INTO classes (course_id, name, start_date, end_date, capacity, instructor_id, schedule) VALUES(?, ?, ?, ?, ?, ?, ?)",[
      course_id,
      code,
      start_date,
      end_date,
      capacity,
      instructor_id,
      schedule
    ]);

    if(result){
      res.status(200).json({message: "Turma adicionada com sucesso!"})
    }else{
      res.status(501).json({message: "Erro ao adicionar turma!"})
    }
  }

  } catch (error) {
    console.error("GET /teachers error:", error);
    return res.status(500).json({ error: "internal_error" });
  }
});



module.exports = router;
